function validateManualClassForm(form,kind){const section=$('[data-db108-manual-class]',form);if(!section)return true;section._db108Sync?.();const enabled=kind==='one_time'||form.elements.class_details_enabled?.checked,error=$('[data-db108-class-error]',section);if(!enabled){if(error)error.innerHTML='';return true;}const fail=message=>{if(error)error.innerHTML=`<div class="error">${H(message)}</div>`;section.scrollIntoView({behavior:'smooth',block:'center'});return false;};if(!String(form.elements.class_name?.value||'').trim())return fail('Enter the class or event name.');if(!parse(form.elements.dance_styles_json?.value).length)return fail('Select at least one dance style.');if(parse(form.elements.class_days_json?.value).length!==Number(form.elements.days_per_week?.value||0))return fail(`Select exactly ${form.elements.days_per_week.value} class days.`);if(form.elements.reminders_enabled?.checked&&!parse(form.elements.reminder_channels_json?.value).length)return fail('Choose at least one reminder channel.');if(kind==='one_time'){const start=form.elements.class_access_start_date?.value,end=form.elements.class_access_end_date?.value;if(!start||!end)return fail('Choose both the class access start date and end date.');if(end<start)return fail('Class access end date must be on or after the start date.');}if(error)error.innerHTML='';return true;}
