function classHelpGuide(kind){
  const oneTime=kind==='one_time',plan=kind==='plan',title=plan?'Add or Edit a Plan / Offer':oneTime?'Create a One-Time Class Payment':'Create a Class Subscription';
  const payment=plan
    ? `<section><h4>1. Plan and price</h4><ul><li><strong>Plan name and short description</strong> are customer-facing. Explain the dance class plainly.</li><li><strong>Plan Features:</strong> each box becomes one short bullet on the public plan card. Use ＋ to add a feature and − to remove one; every feature is limited to 80 characters.</li><li><strong>Payment Type:</strong> Subscription continues according to the billing period. One-Time Payment requires class start and end dates and access ends automatically after the end date.</li><li><strong>Status:</strong> Active can be sold; Draft is preparation; Archived preserves history without offering it.</li><li><strong>Regular and offer price:</strong> the offer price is used only when its switch is on. The Plan Badge is a short label such as Popular, Online or Premium.</li><li>After saving, add plan images and use Product Display to choose the public pages where the plan appears.</li></ul></section>`
    : oneTime
      ? `<section><h4>1. Customer and single payment</h4><ul><li>Enter the customer’s verified name, WhatsApp number and email so the payment and class access can be found later.</li><li>Enter the exact amount and a clear purpose. This link charges once and never renews automatically.</li><li><strong>Class Access Start Date and End Date are required.</strong> Access remains valid through the end date and is revoked the following day.</li></ul></section>`
      : `<section><h4>1. Customer and recurring payment</h4><ul><li>Enter the customer’s verified name, WhatsApp number and email so reminders, receipts and class membership use the correct person.</li><li>Set the recurring amount, billing frequency, start date and total cycles. The live duration is the customer’s payment duration.</li><li>An advance/setup/trial amount is collected today only. Enter 0 when no separate immediate amount is required.</li></ul></section>`;
  return `<div class="db110-help-guide" data-db110-help="${kind}"><header><span>Help &amp; Instructions</span><h3>${title}</h3><p>Complete the payment details first, then connect the customer to the correct dance class, coach and schedule.</p></header>${payment}
    <section><h4>${plan?'2':'2'}. Class or Event Details</h4><ul><li>${oneTime?'This section is always required for a one-time class payment.':'Turn on <strong>Enable class details</strong> when payment should automatically enrol the customer into a class or event.'}</li><li><strong>Class / Event Name</strong> is the clear batch name customers and admins will recognise, for example <em>Beginners Hip Hop — Morning Batch</em>.</li><li><strong>Class Type</strong> decides whether the member is placed under Online, Offline / Studio, Demo, Webinar or Trial.</li><li><strong>Coach:</strong> after a coach is chosen, only the class types and working days saved for that coach remain available. This prevents assigning Friday to a coach available only Monday–Wednesday.</li><li><strong>Dance Styles</strong> may contain more than one specialty and appear in the customer-facing class information.</li></ul><div class="notice"><strong>Example:</strong> select coach Ananya. If her profile allows Online Class and Trial on Monday, Tuesday and Wednesday, the form hides every other class type and day.</div></section>
    <section><h4>3. Public Batch Start Date</h4><ul><li><strong>Coach-safe date:</strong> after you select a coach, the form accepts only dates that fall on that coach’s available weekdays. An unavailable date is cleared immediately and the server also refuses it.</li><li><strong>Leave the date blank:</strong> this is an ongoing weekly batch. Each paid member’s own start date is their payment/access date.</li><li><strong>Choose a date + Hide after the start date ON:</strong> the date creates launch urgency before that date. It automatically disappears from the public page after the date passes, while enrolment into the ongoing batch remains open.</li><li><strong>Choose a date + Hide after the start date OFF:</strong> the date remains visible so customers can see when the ongoing batch originally started.</li></ul><div class="notice"><strong>Campaign example:</strong> if coach Ananya works Monday–Wednesday, choose a date on one of those days. Enter 1 October and turn Hide after the start date on. Visitors see the launch date through 1 October. From 2 October it is hidden, but a new paid customer can still join and their personal start date is their payment date.</div></section>
    <section><h4>4. Weekly schedule and location</h4><ul><li>Set class time, duration and India timezone. Use the joining link for an online class or the studio address for an offline class.</li><li><strong>Number of Days per Week</strong> controls exactly how many Class Days can be selected. After the limit is reached, the remaining available days are disabled.</li><li>The coach’s availability is applied first. If the coach works one day, only that day is shown and the weekly maximum becomes one.</li></ul></section>
    <section><h4>5. Recurring student reminders</h4><ul><li>Turn reminders on only when students should receive a message before every scheduled class.</li><li>Choose how many minutes before class and select at least one configured channel: Email, WhatsApp or SMS.</li><li>A reminder channel must be configured and the student must have a valid destination. Saving a channel does not bypass provider setup or consent.</li></ul></section>
    ${oneTime?`<section><h4>6. One-time access check</h4><ul><li>The access end date cannot be before the start date.</li><li>On the final date the customer can still attend. On the next day, access is treated as ended and the Student Dashboard will prompt them to subscribe or contact the studio.</li></ul></section>`:''}
    <section class="db110-help-check"><h4>Before saving or generating the link</h4><ol><li>Confirm customer, amount and payment model.</li><li>Confirm class name, coach, type and dance style.</li><li>Confirm the selected day count exactly matches Days per Week.</li><li>Confirm the joining link or studio address and reminder channels.</li>${oneTime?'<li>Confirm both mandatory access dates.</li>':''}</ol></section></div>`;
}
